/**
 * Large-company setup: the Jobber quote a crew estimate becomes, and what Jobber's answers mean for it. The lines come
 * from the proposal builder, so the customer sees in Jobber what the salesperson saw on screen: the consultation text
 * first, one priced line per work item (optional and recommended ones marked), then plan and payment terms. Pure.
 */
import type { RateCardDefinition } from './rules.ts';
import type { PricedItem } from './estimate.ts';
import { buildProposal } from './proposal.ts';

export interface JobberLine {
  name: string;
  description: string;
  quantity: number;
  unitPrice: number;
  taxable: boolean;
  optional: boolean;
  recommended: boolean;
  textOnly: boolean;
  saveToProductsAndServices: false;
  unitCost?: number;
}

/** What each line of the quote stands for: the consultation text, a work item, or a terms sentence. */
export interface LineRef { kind: 'consultation' | 'work' | 'terms'; workItemId: string | null }

export interface QuotePlan {
  title: string;
  lineItems: JobberLine[];
  refs: LineRef[];
  discount: { rate: number; type: 'Percent' } | null;
  deposit: { rate: number; type: 'Percent' } | null;
}

export interface QuotePlanInput {
  items: PricedItem[];
  trees: { key: string; label?: string | null }[];
  discountKey?: string | null;
  paymentPlanKey?: string | null;
  salespersonName?: string | null;
  isa?: string | null;
  workWindow?: string | null;
  /** The owner's choice to show unit costs on Jobber lines (production_settings.send_unit_cost), with each item's cost. */
  unitCosts?: Record<string, number> | null;
}

const NAME_MAX = 120;
const TEXT_MAX = 2000;
const cut = (s: string, n: number) => (s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s);
const textLine = (name: string, description: string): JobberLine => ({
  name, description: cut(description, TEXT_MAX), quantity: 1, unitPrice: 0, taxable: false,
  optional: false, recommended: false, textOnly: true, saveToProductsAndServices: false,
});

/** The quote for an estimate. Only priced items go on it; the caller refuses to send an estimate with unpriced items. */
export function quotePlan(def: RateCardDefinition, input: QuotePlanInput): QuotePlan {
  const services = new Map(def.services.map((s) => [s.key, s]));
  const treeLabel = new Map(input.trees.map((t) => [t.key, t.label?.trim() || null]));
  const priced = input.items.filter((i) => i.status === 'ok' && i.price !== null && services.has(i.serviceKey));
  const proposal = buildProposal(def, {
    items: priced.map((i) => ({
      id: i.id, service: services.get(i.serviceKey)!, answers: i.answers, price: i.price as number, kind: i.kind,
      selected: i.selected, recurring: i.recurring, treeLabel: i.treeKey ? treeLabel.get(i.treeKey) ?? null : null,
      unitCost: input.unitCosts?.[i.id] ?? null,
    })),
    salespersonName: input.salespersonName, isa: input.isa, workWindow: input.workWindow,
    discountKey: input.discountKey, paymentPlanKey: input.paymentPlanKey, sendUnitCost: !!input.unitCosts,
  });

  const lineItems: JobberLine[] = [];
  const refs: LineRef[] = [];
  if (proposal.consultationText) {
    lineItems.push(textLine('Consultation', proposal.consultationText));
    refs.push({ kind: 'consultation', workItemId: null });
  }
  for (const l of proposal.lines) {
    lineItems.push({
      name: cut(l.name, NAME_MAX), description: cut(l.description, TEXT_MAX), quantity: l.quantity, unitPrice: l.unitPrice,
      taxable: l.taxable, optional: l.optional, recommended: l.recommended, textOnly: false, saveToProductsAndServices: false,
      ...(l.unitCost !== null ? { unitCost: l.unitCost } : {}),
    });
    refs.push({ kind: 'work', workItemId: l.workItemId });
  }
  for (const t of proposal.termsLines) {
    lineItems.push(textLine('Terms', t));
    refs.push({ kind: 'terms', workItemId: null });
  }
  const plan = input.paymentPlanKey ? def.policies.paymentPlans.find((p) => p.key === input.paymentPlanKey) : undefined;
  return {
    title: cut(proposal.title, NAME_MAX),
    lineItems,
    refs,
    discount: proposal.totals.discount ? { rate: proposal.totals.discount.percent, type: 'Percent' } : null,
    deposit: plan && plan.depositPercent > 0 ? { rate: plan.depositPercent, type: 'Percent' } : null,
  };
}

/** The same quote with text-only lines sent as $0 lines, for an account whose Jobber refuses text-only lines. */
export function withoutTextOnly(plan: QuotePlan): QuotePlan {
  return { ...plan, lineItems: plan.lineItems.map((l) => (l.textOnly ? { ...l, textOnly: false } : l)) };
}

/** Jobber's quoteCreate attributes for a plan (the quote stays a draft: no message, number or transition). */
export function quoteCreateAttributes(plan: QuotePlan, clientId: string, propertyId: string): Record<string, unknown> {
  return {
    clientId, propertyId, title: plan.title, lineItems: plan.lineItems,
    ...(plan.discount ? { discount: plan.discount } : {}),
    ...(plan.deposit ? { deposit: plan.deposit } : {}),
  };
}

export interface JobberQuoteLine { id: string; name?: string | null; sortOrder?: number | null; optional?: boolean | null; recommended?: boolean | null }

/**
 * Each work item's Jobber line id, read back after the quote is made: lines in Jobber's order match the lines sent
 * when the names agree; otherwise the first unused line with the same name. Items not found stay out.
 */
export function matchLineIds(plan: QuotePlan, lines: JobberQuoteLine[]): Record<string, string> {
  const ordered = [...lines].sort((a, b) => (a.sortOrder ?? Number.MAX_SAFE_INTEGER) - (b.sortOrder ?? Number.MAX_SAFE_INTEGER));
  const used = new Set<string>();
  const out: Record<string, string> = {};
  plan.refs.forEach((ref, i) => {
    const sent = plan.lineItems[i];
    const atIndex = ordered[i];
    const hit = atIndex && !used.has(atIndex.id) && atIndex.name === sent.name
      ? atIndex
      : ordered.find((l) => !used.has(l.id) && l.name === sent.name);
    if (!hit) return;
    used.add(hit.id);
    if (ref.kind === 'work' && ref.workItemId) out[ref.workItemId] = hit.id;
  });
  return out;
}

/**
 * The optional and recommended items the customer took when approving in Jobber. Jobber lists the approved lines
 * (lineItems with filter approved); without that list, an optional line's `recommended` flag says whether the customer
 * kept it. An item whose Jobber line isn't known keeps the default: recommended in, optional out.
 */
export function chosenFromQuote(items: Pick<PricedItem, 'id' | 'kind' | 'jobberLineId'>[], lines: JobberQuoteLine[], approvedLineIds: string[] | null): string[] {
  const byId = new Map(lines.map((l) => [l.id, l]));
  const approved = approvedLineIds && approvedLineIds.length ? new Set(approvedLineIds) : null;
  return items.filter((i) => i.kind !== 'required').filter((i) => {
    const lineId = i.jobberLineId ?? null;
    const line = lineId ? byId.get(lineId) : undefined;
    if (!lineId || !line) return i.kind === 'recommended';
    return approved ? approved.has(lineId) : line.recommended === true;
  }).map((i) => i.id);
}

export interface PacketForJob { id: string; jobber_job_id: string | null; scope: { tree: string | null; service: string }[] }

const norm = (s: string) => s.trim().toLowerCase().replace(/\s+/g, ' ');

/**
 * The packets a Jobber job made from the estimate's quote covers. A quote converted into one job covers every packet
 * not linked elsewhere. When the office split it into several jobs, a packet goes with the job holding one of its
 * lines (named as on the quote: "Front oak: Tree removal"). Packets already linked to this job always stay.
 */
export function packetsForJob(packets: PacketForJob[], jobId: string, jobLineNames: string[], quoteJobCount: number): string[] {
  const names = new Set(jobLineNames.map(norm));
  return packets.filter((p) => {
    if (p.jobber_job_id === jobId) return true;
    if (p.jobber_job_id) return false;
    if (quoteJobCount <= 1) return true;
    return p.scope.some((s) => names.has(norm(s.tree ? `${s.tree}: ${s.service}` : s.service)));
  }).map((p) => p.id);
}

/** A plain work window for the consultation text: the promised start, or how long the backlog is. */
export function workWindowText(promisedFrom: string | null | undefined, backlogWeeks: number | null): string | null {
  if (promisedFrom && /^\d{4}-\d{2}-\d{2}$/.test(promisedFrom)) {
    const d = new Date(`${promisedFrom}T12:00:00Z`);
    return `from ${d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', timeZone: 'UTC' })}`;
  }
  if (backlogWeeks === null || !Number.isFinite(backlogWeeks)) return null;
  if (backlogWeeks <= 1) return 'within a week';
  return `in about ${Math.round(backlogWeeks)} weeks`;
}
